# -*- coding: utf-8 -*-
"""Generate 260 unique questions for quiz_data_nature_heritage.py."""

import os

QUESTIONS = []
seen = set()

def add(cat, dest, diff, q, opts, idx, exp):
    q = q.strip()
    assert q not in seen, f"Duplicate question: {q}"
    assert len(opts) == 4, f"Options != 4 in: {q}"
    assert 0 <= idx <= 3, f"Bad index in: {q}"
    seen.add(q)
    QUESTIONS.append({
        "category": cat,
        "destination_tag": dest,
        "difficulty": diff,
        "question_bn": q,
        "options_bn": opts,
        "correct_index": idx,
        "explanation_bn": exp.strip(),
    })

