out_file = os.path.join(os.path.dirname(__file__), "quiz_data_nature_heritage.py")
with open(out_file, "w", encoding="utf-8") as f:
    f.write('"""Bhromon Quiz Engine — Nature, Wildlife, Forests, Rivers, Heritage & History Questions.\n\n')
    f.write('260 Unique, authentic, verified questions on Sundarbans, wetlands, rivers, archaeological sites, and historic architecture.\n"""\n\n')
    f.write('from typing import List, Dict, Any\n\n')
    f.write('NATURE_HERITAGE_QUESTIONS: List[Dict[str, Any]] = [\n')
    for item in QUESTIONS:
        f.write("    " + repr(item) + ",\n")
    f.write("]\n")

print(f"Successfully generated and wrote 260 questions to {out_file}!")
